if(!defined('ABSPATH'))exit;
function bmdkit26_on_page(){return !is_admin()&&is_singular('post')&&(int)get_queried_object_id()===(int)get_option('bmdkit26_post_id',0);}
add_action('wp_head',static function(){if(!bmdkit26_on_page())return;echo '<style id="bmdkit26-css">'.$GLOBALS['bmdkit26css'].'</style>';},110);
$GLOBALS['bmdkit26css']="\n/* Scoped to a single article. WordPress header/sidebar unaffected. */\n.bmdkit26{--bk-ink:#23272e;--bk-text:#44515d;--bk-muted:#76818a;--bk-line:#e3e7eb;--bk-accent:#b32d46;--bk-surface:#f6f8fa;max-width:1070px;margin:0 auto 50px;color:var(--bk-ink);line-height:1.65;font-family:inherit}\n.bmdkit26 *{box-sizing:border-box}\n.bmdkit26 a{overflow-wrap:anywhere}\n.bmdkit26 h2{color:#1d2731!important;font-size:clamp(24px,3vw,33px)!important;line-height:1.2!important;margin:0 0 14px!important;letter-spacing:-.035em!important}\n.bmdkit26 h3{font-size:17px!important;color:#27313c!important;line-height:1.32!important;margin:0 0 8px!important}\n.bmdkit26 p{line-height:1.65!important}\n.bmdkit26 .bk-disclosure{background:#fff9fa;border:1px solid #f0dde2;padding:13px 16px;border-radius:12px;font-size:12px!important;color:#53606b!important;margin:16px 0 20px!important}\n.bmdkit26 .bk-hero{min-height:365px;display:grid;grid-template-columns:1.18fr .82fr;background:#222936;color:white;border-radius:22px;overflow:hidden;position:relative}\n.bmdkit26 .bk-hero-left{position:relative;z-index:2;padding:clamp(26px,4vw,45px);display:flex;flex-direction:column;align-items:flex-start;justify-content:center}\n.bmdkit26 .bk-hero h2{color:#fff!important;font-size:clamp(29px,4vw,43px)!important;line-height:1.12!important;max-width:600px;margin:12px 0 17px!important}\n.bmdkit26 .bk-hero-left>p:not(.bk-eyebrow){font-size:15px!important;color:#d8e0e8!important;max-width:650px;margin:0 0 17px!important}\n.bmdkit26 .bk-eyebrow{font-size:10px!important;letter-spacing:.14em;color:#f2aabd!important;font-weight:800!important}\n.bmdkit26 .bk-primary-scroll{display:inline-flex;align-items:center;gap:14px;padding:12px 17px;border-radius:10px;background:#bf4058;color:white!important;font-size:13px;font-weight:800;text-decoration:none!important;margin:7px 0 17px}\n.bmdkit26 .bk-hero-facts{display:flex;flex-wrap:wrap;gap:7px}\n.bmdkit26 .bk-hero-facts span{color:#e9ecf0;font-size: