;margin:6px 0 10px!important}\n.bmdkit26 .bk-product a{font-size:12px!important;font-weight:800;color:#ffc1cb!important;text-decoration:underline!important;text-underline-offset:3px}\n.bmdkit26 .bk-product .bk-no-link{font-size:11px;color:#bbc5ce}\n.bmdkit26 .bk-preview-foot{padding:16px 24px 23px;background:#1e2731}\n.bmdkit26 .bk-preview-foot>p{font-size:11px!important;color:#cad3d9!important;line-height:1.55!important;margin:0 0 12px!important}\n.bmdkit26 .bk-copy{background:#f5f7f8!important;border:0!important;border-radius:10px!important;padding:10px 16px!important;font-size:12px!important;color:#27303b!important;font-weight:800!important;cursor:pointer}\n.bmdkit26 #bk-feedback{display:block;font-size:11px;margin-top:8px;color:#cdd7de}\n.bmdkit26 .bk-principles-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}\n.bmdkit26 .bk-principles-grid article{border:1px solid var(--bk-line);border-radius:17px;padding:23px 20px;background:#fff;display:flex;flex-direction:column}\n.bmdkit26 .bk-principle-icon{width:42px;height:42px;border:1px solid #f0d0d8;border-radius:12px;display:grid;place-items:center;background:#fff1f4;color:#b12f48;font-weight:800;font-size:13px;margin-bottom:22px}\n.bmdkit26 .bk-principles-grid article p{font-size:12px!important;color:#5a6873!important;margin:0 0 14px!important}\n.bmdkit26 .bk-principles-grid article strong{font-size:11px;color:#a32f46;margin-top:auto}\n.bmdkit26 .bk-setup-layout{display:grid;grid-template-columns:1fr .9fr;gap:20px}\n.bmdkit26 .bk-room{position:relative;min-height:310px;border:1px solid #e4e9ed;border-radius:18px;background:repeating-linear-gradient(0deg,#f5f7f8 0 24px,#e9edef 25px),repeating-linear-gradient(90deg,#f5f7f8 0 24px,#e9edef 25px);overflow:hidden}\n.bmdkit26 .bk-room-top{position:absolute;top:14px;left:46%;color:#77838d;font-size:10px;font-weight:800}\n.bmdkit26 .bk-room-person{position:absolute;left:45%;top:31%;width:82px;height:82px;border:12px solid #edf5f5;background:#467e80;border-radius:50%;box-shadow:0 7px 23px #1f6a6a30}\n.bmdkit26 .bk-room-person span{display:block;width:25px;height:25px;background:#d3a99e;border-radius:50%;margin:15px auto}\n.bmdkit26 .bk-room-connector{position:absolute;top:57%;left:50%;height:70px;width:2px;background:#b9bec4}\n.bmdkit26 .bk-room-camera{position:absolute;bottom:21px;left:39%;background:#26333d;color:#fff;border-radius:11px;padding:12px 20px;font-size:11px;font-weight:800}\n.bmdkit26 .bk-room-light{position:absolute;top:28%;left:8%;padding:13px;border-radius:50%;width:76px;height:76px;background:#ffe8b6;border:8px solid #f3c879;color:#564424;display:grid;place-items:center;text-align:center;font-size:11px;font-weight:800;box-shadow:0 0 0 16px #f5e6c579}\n.bmdkit26 .bk-room-angle{position:absolute;left:25%;top:41%;width:100px;height:2px;background:#e8bd75;transform:rotate(30deg)}\n.bmdkit26 .bk-setup-notes{display:grid;gap:9px}\n.bmdkit26 .bk-setup-notes>div{display:flex;gap:12px;align-items:flex-start;border:1px solid var(--bk-line);padding:13px 15px;border-radius:12px;background:#fff}\n.bmdkit26 .bk-setup-notes span{flex:none;color:#a73249;font-size:12px;font-weight:800}\n.bmdkit26 .bk-setup-notes p{font-size:12px!important;color:#5b6873!important;margin:0!important}\n.bmdkit26 .bk-about{padding:24px;border-radius:17px;background:#f5f7f8;border:1px solid var(--bk-line);margin:40px 0}\n.bmdkit26 .bk-about p{font-size:12.5px!important;color:#56636e!important}\n.bmdkit26 .bk-faq details{border:1px solid var(--bk-line);border-radius:12px;margin-bottom:8px;background:#fff;overflow:hidden}\n.bmdkit26 .bk-faq summary{padding:16px 18px;cursor:pointer;font-size:14px;font-weight:800;color:#293540}\n.bmdkit26 .bk-faq details[open] summary{border-bottom:1px solid var(--bk-line);color:#a62d44}\n.bmdkit26 .bk-faq details p{margin:0!important;padding:15px 18px!important;font-size:13px!important;color:#586671!important}\n.bmdkit26 .bk-related{margin:37px 0}\n.bmdkit26 .bk-related p{font-size:13px!important}\n.bm